pay_with:
query PayWithQuery($token: String!, $experiences: [ThreeDSPaymentExperience], $withSplitTender: Boolean = false) {
  checkoutSession(token: $token) {
    declinedInstruments {
      ...DeclinedInstrumentFragment
      __typename
    }
    disallowedInstruments {
      ...DisallowedInstrumentFragment
      __typename
    }
    fundingOptions(returnAllPlans: true, groupSourcesOnType: INCENTIVE) {
      ...FundingOptionFragment
      __typename
    }
    splitFundingOptions @include(if: $withSplitTender) {
      ...SplitFundingOptionsFragment
      __typename
    }
    cart {
      intent
      amounts {
        total {
          currencyValue
          currencyFormat
          currencyCode
          currencyFormatSymbolISOCurrency
          __typename
        }
        __typename
      }
      category
      billingChargePattern
      __typename
    }
    flags {
      allowAddresslessAddCard
      is3DSecureRequired
      isIncentivePresent
      isPadPreferred
      hasPPCreditInstallments
      isCreditSecondButton
      showPPCreditOffer
      hideCart
      showRemittanceDisclosure
      __typename
    }
    paymentContingencies {
      ...PaymentContingenciesFragment
      __typename
    }
    creditFinancingOption {
      ...CreditFinancingOptionFragment
      __typename
    }
    userAction
    checkoutSessionType
    merchant {
      country
      isGambling
      isTrustedBeneficiary
      __typename
    }
    secureCustomerAuthenticationContext {
      status
      exemptReason
      __typename
    }
    buyer {
      userId
      __typename
    }
    __typename
  }
}

