ship_to:
query ShipToQuery($token: String!) {
  checkoutSession(token: $token) {
    merchant {
      name
      __typename
    }
    shippingAddresses {
      ...ShippingAddressesFragment
      __typename
    }
    flags {
      isChangeShippingAddressAllowed
      hideShipping
      blockNonDomesticShipping
      isOptionallyShareAddress
      isSntSupported
      __typename
    }
    cart {
      total {
        currencyFormatSymbolISOCurrency
        currencyCode
        currencyValue
        __typename
      }
      amounts {
        ...ShippingCartAmountFragment
        __typename
      }
      shippingMethods {
        id
        type
